// Normalize to a friendlier shape used across the app.
export const ELEMENT_MAP = ELEMENTS.reduce((acc, e) => {
  acc[e.z] = {
    atomic_number: e.z,
    symbol: e.s,
    name: e.name,
    atomic_mass: e.mass,
    category: e.cat,
    group: e.g,
    period: e.p,
    block: e.b,
    phase: e.phase,
    density: e.density,
    melting_point: e.melt,
    boiling_point: e.boil,
    electronegativity: e.en,
    electron_configuration: e.ec,
    electron_configuration_noble: e.ecn,
    valence_electrons: e.val,
    oxidation_states: e.ox,
    discovered_by: e.disc,
    discovery_year: e.year,
    appearance: e.appearance,
    radioactive: e.radio,
    synthetic: e.synth,
    atomic_radius: e.radius,
    ionization_energy: e.ie,
    uses: e.uses,
    summary: e.summary,
    cas: e.cas,
  };
  return acc;
}, {});

export const ALL_ELEMENTS = Object.values(ELEMENT_MAP);

export function getElement(z) {
  return ELEMENT_MAP[z] || null;
}
export function getElementBySymbol(sym) {
  return ALL_ELEMENTS.find((e) => e.symbol === sym);
}